local LeatherConditionerMaker = {}
local PRODUCTS = {
    iron_leather_conditioner = { name = "Železni kondicioner za usnje", ironCost = 1, woodCost = 1, leatherCost = 4, time = 5, cost = 155, prestige = 4, happiness = 2, description = "Železni kondicioner za mehčanje usnja." },
    bronze_leather_conditioner = { name = "Bronast kondicioner za usnje", bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 4, time = 7, cost = 380, prestige = 6, happiness = 3, description = "Bronast kondicioner za negovano usnje." },
    silver_leather_conditioner = { name = "Srebrni kondicioner za usnje", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 4, time = 11, cost = 920, prestige = 11, happiness = 4, description = "Srebrni kondicioner za plemiško usnje." },
    gilded_leather_conditioner = { name = "Pozlačeni kondicioner za usnje", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 4, time = 15, cost = 1980, prestige = 20, happiness = 5, description = "Pozlačeni kondicioner za dvorno usnje." },
    jewel_set_leather_conditioner = { name = "Draguljasti kondicioner za usnje", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 4, time = 19, cost = 4280, prestige = 36, happiness = 7, description = "Draguljasti kondicioner za kraljevsko usnje." },
    royal_sovereign_leather_conditioner = { name = "Kraljevski suvereni kondicioner za usnje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 5, time = 26, cost = 9200, prestige = 69, happiness = 13, description = "Suvereni kondicioner z biseri za krono." },
}
local BUILDINGS = {
    leatherconditioner_workshop = { name = "Kondicionerna delavnica", cost = { gold = 315, wood = 175, stone = 130, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    leatherconditioner_house = { name = "Kondicionerna hiša", cost = { gold = 1165, wood = 360, stone = 265, silver = 7, iron = 7 }, upkeep = 24, qualityBonus = 18 },
    master_leatherconditioner_atelier = { name = "Mojstrski kondicionerni atelje", cost = { gold = 2935, wood = 420, stone = 510, silver = 34, gold = 7 }, upkeep = 69, qualityBonus = 30 },
    sovereign_leatherconditioner_palace = { name = "Suverena kondicionerna palača", cost = { gold = 12780, wood = 645, stone = 820, gold = 82, jewel = 19 }, upkeep = 251, qualityBonus = 55, prestigeBonus = 50 },
}
LeatherConditionerMaker.ironStock = 8; LeatherConditionerMaker.bronzeStock = 6; LeatherConditionerMaker.woodStock = 14; LeatherConditionerMaker.leatherStock = 20; LeatherConditionerMaker.silverStock = 8; LeatherConditionerMaker.goldStock = 6; LeatherConditionerMaker.jewelStock = 4; LeatherConditionerMaker.pearlStock = 4
LeatherConditionerMaker.productStock = {}; LeatherConditionerMaker.buildings = {}; LeatherConditionerMaker.maker = nil; LeatherConditionerMaker.activeMaking = {}; LeatherConditionerMaker.totalProducts = 0; LeatherConditionerMaker.dayTimer = 0
function LeatherConditionerMaker.init() LeatherConditionerMaker.ironStock=8; LeatherConditionerMaker.bronzeStock=6; LeatherConditionerMaker.woodStock=14; LeatherConditionerMaker.leatherStock=20; LeatherConditionerMaker.silverStock=8; LeatherConditionerMaker.goldStock=6; LeatherConditionerMaker.jewelStock=4; LeatherConditionerMaker.pearlStock=4; LeatherConditionerMaker.productStock={}; LeatherConditionerMaker.buildings={}; LeatherConditionerMaker.maker=nil; LeatherConditionerMaker.activeMaking={}; LeatherConditionerMaker.totalProducts=0; LeatherConditionerMaker.dayTimer=0; print("[LeatherConditionerMaker] Royal Leather Conditioner Maker System initialized (6 products, 4 buildings)") end
function LeatherConditionerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LeatherConditionerMaker.maker={name=n or ("Kondicionar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kondicionar najet: %s (spretnost: %d)",LeatherConditionerMaker.maker.name,s),"success") end; return true end
function LeatherConditionerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LeatherConditionerMaker.build(id) local ok,e=LeatherConditionerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LeatherConditionerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LeatherConditionerMaker.getQualityBonus() local b=0; for _,bd in ipairs(LeatherConditionerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LeatherConditionerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and LeatherConditionerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and LeatherConditionerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and LeatherConditionerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and LeatherConditionerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and LeatherConditionerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LeatherConditionerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LeatherConditionerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LeatherConditionerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LeatherConditionerMaker.buildings==0 then return false,"Potrebna kondicionerna delavnica" end; if not LeatherConditionerMaker.maker then return false,"Potreben kondicionar" end; return true end
function LeatherConditionerMaker.make(pt,qty) qty=qty or 1; local ok,e=LeatherConditionerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then LeatherConditionerMaker.ironStock=LeatherConditionerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then LeatherConditionerMaker.bronzeStock=LeatherConditionerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then LeatherConditionerMaker.woodStock=LeatherConditionerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then LeatherConditionerMaker.leatherStock=LeatherConditionerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then LeatherConditionerMaker.silverStock=LeatherConditionerMaker.silverStock-d.silverCost*qty end; if d.goldCost then LeatherConditionerMaker.goldStock=LeatherConditionerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LeatherConditionerMaker.jewelStock=LeatherConditionerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LeatherConditionerMaker.pearlStock=LeatherConditionerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LeatherConditionerMaker.maker then t=math.max(1,t-math.floor(LeatherConditionerMaker.maker.skill/13)) end; table.insert(LeatherConditionerMaker.activeMaking,{id="leatherconditioner_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LeatherConditionerMaker.completeMaking(m) local q=1.0+(LeatherConditionerMaker.getQualityBonus()/100); if LeatherConditionerMaker.maker then q=q+(LeatherConditionerMaker.maker.skill/140) end; q=math.min(2.5,q); LeatherConditionerMaker.productStock[m.productType]=(LeatherConditionerMaker.productStock[m.productType] or 0)+m.quantity; LeatherConditionerMaker.totalProducts=LeatherConditionerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LeatherConditionerMaker.maker then LeatherConditionerMaker.maker.itemsMade=LeatherConditionerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LeatherConditionerMaker.maker.skill=math.min(100,LeatherConditionerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kondicioner izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"leatherconditioner.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function LeatherConditionerMaker.update(dt) if not _G.state then return end; LeatherConditionerMaker.dayTimer=LeatherConditionerMaker.dayTimer+dt; if LeatherConditionerMaker.dayTimer>=30 then LeatherConditionerMaker.dayTimer=0; for i=#LeatherConditionerMaker.activeMaking,1,-1 do local m=LeatherConditionerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LeatherConditionerMaker.completeMaking(m); table.remove(LeatherConditionerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LeatherConditionerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LeatherConditionerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LeatherConditionerMaker.getStats() return {ironStock=LeatherConditionerMaker.ironStock,bronzeStock=LeatherConditionerMaker.bronzeStock,woodStock=LeatherConditionerMaker.woodStock,leatherStock=LeatherConditionerMaker.leatherStock,silverStock=LeatherConditionerMaker.silverStock,goldStock=LeatherConditionerMaker.goldStock,jewelStock=LeatherConditionerMaker.jewelStock,pearlStock=LeatherConditionerMaker.pearlStock,productStock=LeatherConditionerMaker.productStock,numBuildings=#LeatherConditionerMaker.buildings,hasMaker=LeatherConditionerMaker.maker~=nil,makerName=LeatherConditionerMaker.maker and LeatherConditionerMaker.maker.name or "—",makerSkill=LeatherConditionerMaker.maker and LeatherConditionerMaker.maker.skill or 0,activeMaking=#LeatherConditionerMaker.activeMaking,totalProducts=LeatherConditionerMaker.totalProducts} end
return LeatherConditionerMaker
